import assert from 'node:assert/strict';
import fs from 'node:fs';
const read=(name)=>fs.readFileSync(name,'utf8');
const leads=read('src/crm/components/CrmSheetLeadsImport.tsx');
const importer=read('server/_crm-sheet-import.ts');
const handler=read('server/crm/sheet-leads.ts');
assert.match(leads,/SHEET_LEAD_BATCH_SIZE\s*=\s*3/);
assert.match(leads,/while \(index < unique\.length\)/);
assert.match(leads,/retrySheetLeadRequest/);
assert.match(leads,/batchSize = 1/);
assert.match(leads,/setResumeFrom\(index\)/);
assert.match(leads,/importRows\(resumeFrom \?\? 0\)/);
assert.match(read('src/crm/sheetLeadImportTransport.ts'),/x-vercel-id/);
assert(importer.indexOf('findExistingPhone(check.phoneNormalized, legacyCache)') < importer.indexOf('chooseSheetImportAssignment(serviceKey)'));
assert.match(importer,/tryWithDatabaseAdvisoryLock\("crm:sheet-lead-bulk-import"/);
assert.match(handler,/platform\.superadmin/);
console.log('PASS: CRM incremental import uses short batches, recoverable failure, and immutable assignments for existing phones');
const detail=read('src/marketing/workflow/TaskDetail.tsx');
const workflow=read('server/marketing/workflow.ts');
assert.match(detail,/openedRequirementId/);
assert.match(detail,/mkw-requirement-review-toggle/);
assert.match(detail,/workPost\('review', \{ itemId: item\.id, version: version\.current, decision,\s*\.\.\.\(formatId \? \{ formatId \} : \{\}\), note:/);
assert.match(detail,/const hasSubmitted = \(item\.format_reviews \|\| \[\]\)\.some\(row => row\.status === 'submitted'\)/);
assert.match(workflow,/const pending = \(item\?\.format_reviews \|\| \[\]\)\.filter\(row => row\.status === 'submitted'\)/);
assert.match(workflow,/const targets = requestedFormat \? pending\.filter\(row => row\.format_id === requestedFormat\) : pending/);
assert.match(workflow,/const completelyApproved = item\.formats\.every\(format => statuses\.get\(format\.id\) === 'approved'\)/);
assert.match(workflow,/where id=\$\{itemId\}::uuid/);
assert.match(workflow,/const readiness = await recalculateTask\(tx, locked\.task_id\)/);
console.log('PASS: individual requirement review is backed by per-item concurrency controls and accurate task readiness');
const publish=read('src/marketing/workflow/PublishPage.tsx');
const dash=read('src/marketing/pages/MarketingDashboardPage.tsx');
assert.match(publish,/workPost\('save_product_draft', \{ productId: product\.id/);
assert.match(publish,/draft\?\.caption\?\.trim\(\)/);
assert.match(publish,/draft\?\.hashtags\?\.trim\(\)/);
assert.match(publish,/mkw-publish-copy-field/);
assert.match(dash,/line\.prepared_count === 1 && !line\.failed_count/);
console.log('PASS: caption and hashtags save independently for each output and the published checklist is based on saved state');
const create=read('src/marketing/workflow/CreatePage.tsx');
assert.doesNotMatch(create,/const \[productSearch, setProductSearch\]/);
assert.match(create,/mkw-plan-product-preview/);
assert.match(create,/selectableGroups.map\(group => <optgroup/);
assert.match(create,/availablePlanProducts\(products, entries, entry.key\)/);
assert.match(create,/معاينة جدول/);
assert.match(create,/previewRows.map/);
assert.match(create,/ProductViewButton id=\{product\.id\}/);
assert.match(create,/kind=\{mode as 'campaign' \| 'agenda'\}/);
console.log('PASS: campaign and agenda choose required items by task, display the idea and preview the schedule without saving');
